use serde_json::Value;
use std::{io::Write, path::Path, process::{Command,Stdio}};

fn validate_document(path:&Path,must_exist:bool)->Result<(),String>{let extension=path.extension().and_then(|value|value.to_str()).unwrap_or("").to_ascii_lowercase();let allowed=if must_exist{["docx","md","markdown","txt","html","htm","epub"].as_slice()}else{["docx","md","markdown","txt","html","htm","epub","pdf"].as_slice()};if !allowed.contains(&extension.as_str()){return Err(format!("Unsupported document format: .{extension}"))}if must_exist&&!path.is_file(){return Err("The selected manuscript file does not exist".into())}Ok(())}
fn result(output:std::process::Output)->Result<Value,String>{let payload:Value=serde_json::from_slice(&output.stdout).map_err(|_|format!("Document worker returned unreadable output: {}",String::from_utf8_lossy(&output.stderr)))?;if !output.status.success()||payload.get("ok").and_then(Value::as_bool)!=Some(true){return Err(payload.get("error").and_then(Value::as_str).unwrap_or("Document worker failed").to_string())}Ok(payload.get("result").cloned().unwrap_or_default())}
pub fn inspect(path:&Path,worker:&Path)->Result<Value,String>{validate_document(path,true)?;if !worker.is_file(){return Err(format!("Document worker resource was not found at {}",worker.display()))}let output=Command::new("python3").arg(worker).arg("inspect").arg("--input").arg(path).output().map_err(|error|format!("Could not start the document worker: {error}. Install Python 3 and the bundled document dependencies."))?;result(output)}
pub fn export(path:&Path,payload:&Value,worker:&Path)->Result<Value,String>{validate_document(path,false)?;if !worker.is_file(){return Err(format!("Document worker resource was not found at {}",worker.display()))}let mut child=Command::new("python3").arg(worker).arg("export").arg("--output").arg(path).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().map_err(|error|format!("Could not start the document worker: {error}. Install Python 3 and the bundled document dependencies."))?;child.stdin.take().ok_or_else(||"Could not open document worker input".to_string())?.write_all(serde_json::to_string(payload).map_err(|error|error.to_string())?.as_bytes()).map_err(|error|error.to_string())?;result(child.wait_with_output().map_err(|error|error.to_string())?)}
